def allowed(path,family,root):
    expected = EXPECTED if family == 'protected' else BODY_EXPECTED if family == 'bodies' else {}
    if path not in expected: return False
    p=Path(root)/path
    if not p.is_file(): return False
    raw=p.read_bytes()
    if family == 'bodies':
        body=re.search(rb'<body\b[\s\S]*',raw,re.I);raw=body[0] if body else b''
    return hashlib.sha256(raw).hexdigest()==expected[path]
